/* Fixed foundation of the recipe: fonts, reset and the scene frame. Brand values are in tokens.css, not here. */
@font-face { font-family: "Inter"; font-weight: 400; src: url("/assets/fonts/Inter-Regular.otf") format("opentype"); }
@font-face { font-family: "Inter"; font-weight: 700; src: url("/assets/fonts/Inter-Bold.otf") format("opentype"); }
@font-face { font-family: "Inter"; font-weight: 800; src: url("/assets/fonts/Inter-ExtraBold.otf") format("opentype"); }
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: var(--w); height: var(--h); overflow: hidden; background: var(--bg); color: var(--text); font-family: var(--font-body); }
.scene { position: absolute; inset: 0; overflow: hidden; }
h1, h2 { font-family: var(--font-display); font-weight: 800; line-height: 1.04; letter-spacing: -0.02em; }
.acc { color: var(--accent); }

/* Brand and layout tokens for every scene (recipe data-infographic). Edit values here: every scene that imports this file
   re-renders, which is correct, because they all depend on it. */
:root {
  --bg: {{brand.bg}};
  --main: {{brand.main}};
  --accent: {{brand.accent}};
  --text: {{brand.text}};
  --text-on-accent: {{brand.text_on_accent}};
  --surface: color-mix(in srgb, var(--text) 8%, var(--bg));
  --text-dim: color-mix(in srgb, var(--text) 68%, var(--bg));
  --font-display: "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --w: {{format.width}}px;
  --h: {{format.height}}px;
  --type-scale: {{style.font_scale}};
  --pace: {{derived.pace}};
  --fs-display: {{format.vars.fs_display}}px;
  --fs-body: {{format.vars.fs_body}}px;
  --fs-figure: {{format.vars.fs_figure}}px;
  --chart-h: {{format.vars.chart_h}}px;
  --margin: {{format.vars.margin}}px;
}

