h1, h2 { font-family: var(--font-display); font-weight: 800; line-height: 1.04; letter-spacing: -0.02em; }
.acc { color: var(--accent); }

/* Brand and layout tokens for every scene (recipe data-infographic). Edit values here: every scene that imports this file
   re-renders, which is correct, because they all depend on it. */
:root {
  --bg: #0b1020;
  --main: #38bdf8;
  --accent: #f59e0b;
  --text: #f8fafc;
  --text-on-accent: #0b1020;
  --surface: color-mix(in srgb, var(--text) 8%, var(--bg));
  --text-dim: color-mix(in srgb, var(--text) 68%, var(--bg));
  --font-display: "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --w: 1920px;
  --h: 1080px;
  --type-scale: 1;
  --pace: 1;
  --fs-display: 112px;
  --fs-body: 60px;
  --fs-figure: 330px;
  --chart-h: 560px;
  --margin: 140px;
}
